import './registerServiceWorker';

// iOS PWA 不支持 overscroll-behavior CSS，需用 JS 阻止下拉刷新
// window.navigator.standalone 仅在 iOS 独立模式下为 true
if (window.navigator.standalone === true) {
    let touchStartY = 0;
    document.addEventListener('touchstart', function(e) {
        touchStartY = e.touches[0].clientY;
    }, { passive: true });
    document.addEventListener('touchmove', function(e) {
        // 手指向下滑（Y 增大）= 试图向上翻过顶部 = PTR 手势
        if (e.touches[0].clientY <= touchStartY) return;
        // 向上找最近的可滚动祖先
        let el = e.target;
        while (el && el !== document.documentElement) {
            const s = window.getComputedStyle(el);
            if ((s.overflowY === 'auto' || s.overflowY === 'scroll') && el.scrollTop > 0) {
                // 可滚动且不在顶端——用户在容器内向上回滚，放行
                return;
            }
            el = el.parentElement;
        }
        // 已在顶端或无可滚动祖先——阻止 PTR
        e.preventDefault();
    }, { passive: false });
}

import Vue from 'vue';
import App from './App.vue';
import store from './store';
import vuetify from './plugins/vuetify';
import { newGame, loadGame } from './js/init';
import { checkLocal } from './js/savefile';
import gbPlugin from './gbPlugin';
import "@fontsource/roboto/400.css";
import "@fontsource/roboto/500.css";
import "@fontsource/roboto/900.css";
import "@fontsource/caveat/400.css";
import "@fontsource/roboto-mono/400.css";
import GoobooTooltip from './components/partial/render/GoobooTooltip.vue';
import { APP_TESTING } from './js/constants';

Vue.config.productionTip = false

Vue.use(gbPlugin);

// Handle javascript errors
window.onerror = function(message, source, line, column) {
    store.commit('system/addNotification', {color: 'error', timeout: -1, message: {
        type: 'error',
        tech: 'javascript',
        source,
        message,
        line,
        column
    }});
};

const localFile = checkLocal();

if (localFile) {
    if (!loadGame(localFile)) {
        newGame();
    }
} else {
    newGame();
}

Vue.component('gb-tooltip', GoobooTooltip);

new Vue({
    vuetify,
    store,
    render: h => h(App),

    // Handle vue.js errors
    errorCaptured: function(err) {
        store.commit('system/addNotification', {color: 'error', timeout: -1, message: {
            type: 'error',
            tech: 'vuejs',
            source: err.fileName,
            message: err.message,
            line: err.lineNumber,
            column: err.columnNumber
        }});
    }
}).$mount('#app')

// Duplicate tab check
const channel = new BroadcastChannel(APP_TESTING ? 'tabtest' : 'tab');
let isOriginal = true;
channel.postMessage('another-tab');
channel.addEventListener('message', (msg) => {
    if (msg.data === 'another-tab' && isOriginal) {
        channel.postMessage('already-open');
    }
    if (msg.data === 'already-open') {
        isOriginal = false;
        store.commit('system/updateKey', {key: 'screen', value: 'tab-duplicate'});
    }
});
